sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        if (!current.getValue('asset_lifecycle_number')) {
            var nm = new global.NumberManager(current.getTableName());
            current.setValue('asset_lifecycle_number', nm.getNextObjNumberPadded());
            gs.info('AALE numbering: set ' + current.getValue('asset_lifecycle_number'));
        }
    } catch (e) {
        gs.error('AALE numbering failed: ' + e);
    }
})(current, previous);
